<script setup lang="ts">
const config = useRuntimeConfig()
const route = useRoute()
useSeoMeta({ title: 'Start a project — Rumi Works', description: 'Put together a simple project brief for a website or custom software project. No account needed. Your draft stays in this browser until you choose to share it.' })
const packages: Record<string, string> = { launch: 'Launch website — RM990 proposed', business: 'Business website — RM2,490 proposed', growth: 'Growth website — RM4,490 proposed' }
const projectType = ref('Business website')
// Read package hints after hydration: one static HTML file serves every query string.
onMounted(() => { projectType.value = packages[String(route.query.package)] || 'Business website' })
watch(() => route.query.package, (value) => { projectType.value = packages[String(value)] || 'Business website' })
const business = ref('')
const goals = ref('')
const budget = ref('Not decided yet')
const timing = ref('Flexible / exploring')
const status = ref('')
const brief = computed(() => `Hello Rumi Works, I’d like to discuss a project.\n\nBusiness: ${business.value.trim() || 'To discuss'}\nProject: ${projectType.value}\nWhat I need: ${goals.value.trim() || 'To discuss'}\nBudget: ${budget.value}\nTiming: ${timing.value}\n\nPlease help me understand a suitable scope and next steps.`)
const whatsapp = computed(() => /^\d{8,15}$/.test(String(config.public.whatsapp)) ? String(config.public.whatsapp) : '')
const email = computed(() => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(config.public.contactEmail)) && !/[\r\n]/.test(String(config.public.contactEmail)) ? String(config.public.contactEmail) : '')
const whatsappUrl = computed(() => `https://wa.me/${whatsapp.value}?text=${encodeURIComponent(brief.value)}`)
const emailUrl = computed(() => `mailto:${email.value}?subject=${encodeURIComponent('Project enquiry — Rumi Works')}&body=${encodeURIComponent(brief.value)}`)
const briefField = ref<HTMLTextAreaElement | null>(null)
async function copyBrief() {
  status.value = ''
  try { await navigator.clipboard.writeText(brief.value); status.value = 'Brief copied. Nothing has been sent.' }
  catch { briefField.value?.focus(); briefField.value?.select(); status.value = 'Clipboard access is unavailable. Your brief is selected—use your device’s copy command.' }
}
watch([business, goals, budget, timing, projectType], () => { status.value = '' })
</script>
<template>
  <section class="page-hero container contact-hero"><p class="eyebrow">LET’S START WITH WHAT YOU NEED</p><h1 class="display-title">Good things start<br>with a conversation.</h1><p class="lead">You don’t need a perfect brief. A little context about your business and what you have in mind is a good place to start.</p></section>
  <section class="container contact-grid"><div class="brief-form"><div class="form-heading"><span class="eyebrow">01 / YOUR STARTING POINT</span><h2>Tell us a little.</h2><p>This tool creates a brief you can copy. It does not submit a form or send us your details.</p></div><div class="field"><label for="business">Your business <span>(optional)</span></label><input id="business" v-model="business" maxlength="120" autocomplete="organization" placeholder="Business name or a little about what you do"></div><div class="field"><label for="project">What are you looking for?</label><select id="project" v-model="projectType"><option>Business website</option><option>Landing page</option><option>Website with a CMS</option><option>Custom software / internal tool</option><option>Not sure yet</option><option v-for="(name, key) in packages" :key="key">{{ name }}</option></select></div><div class="field"><label for="goals">What would you like to make better?</label><textarea id="goals" v-model="goals" maxlength="1800" rows="5" placeholder="A clearer website, easier enquiries, less manual admin…"></textarea><span class="field-help">Please don’t include passwords, financial records, or other sensitive information.</span></div><div class="form-row"><div class="field"><label for="budget">Indicative budget</label><select id="budget" v-model="budget"><option>Not decided yet</option><option>Under RM2,000</option><option>RM2,000–5,000</option><option>RM5,000–10,000</option><option>RM10,000+</option></select></div><div class="field"><label for="timing">When are you thinking?</label><select id="timing" v-model="timing"><option>Flexible / exploring</option><option>Within a month</option><option>In 1–3 months</option><option>More than 3 months away</option></select></div></div></div>
    <aside class="brief-preview"><span class="eyebrow">02 / YOUR CONVERSATION STARTER</span><h2>A simple starting brief.</h2><textarea ref="briefField" class="generated-brief" aria-label="Your generated project brief" :value="brief" readonly rows="13"></textarea><button class="button button-dark" type="button" @click="copyBrief">Copy project brief <span aria-hidden="true">↗</span></button><p class="copy-status" role="status" aria-live="polite">{{ status || 'Your draft stays here. Nothing is saved or submitted.' }}</p><div v-if="whatsapp || email" class="contact-channels"><p>Ready to share? Choose a channel. Review the message before sending.</p><a v-if="whatsapp" class="button button-outline" :href="whatsappUrl" target="_blank" rel="noopener noreferrer">Open WhatsApp <span aria-hidden="true">↗</span></a><a v-if="email" class="button button-outline" :href="emailUrl">Open email app <span aria-hidden="true">↗</span></a></div><div v-else class="setup-notice"><span class="status-dot" /><div><strong>Contact channels are being set up.</strong><p>WhatsApp and email aren’t configured for this preview yet. You can prepare and copy your brief, but it won’t reach Rumi Works from this page.</p><div class="contact-placeholders"><span>hello@rumiworks.example <small>Placeholder only</small></span><span>+60 XX-XXX XXXX <small>Placeholder only</small></span><span class="small-note">Email and WhatsApp sending are disabled until real details are configured.</span></div></div></div><NuxtLink class="privacy-note" to="/privacy">How this page handles your information ↗</NuxtLink></aside></section>
  <section class="section container"><div class="section-heading"><p class="eyebrow">A LITTLE CONTEXT GOES A LONG WAY</p><h2>Helpful things to think about.</h2></div><div class="three-col"><div class="info-card"><span class="eyebrow">01</span><h3>What’s not working?</h3><p>Start with the problem, not the technology. Where do customers get stuck, or where does your team lose time?</p></div><div class="info-card"><span class="eyebrow">02</span><h3>What does better look like?</h3><p>A clearer offer, easier content updates, or one place to manage a process. Pick the most important outcome.</p></div><div class="info-card"><span class="eyebrow">03</span><h3>What are the boundaries?</h3><p>An indicative budget, a real deadline, and who needs to be involved help shape a sensible scope.</p></div></div></section>
</template>
